class CheckoutService {
  private inventory: InventoryService;
  private payment: PaymentService;
  private notify: NotificationService;

  async completeOrder(order: Order) {
    const reserved = await this.inventory.reserve(order.items);
    const paid = await this.payment.charge(order.paymentInfo, reserved.total);
    await this.notify.sendReceipt(order.customer, paid.receiptId);
    return { reserved, paid };
  }
}

/* Version A */
class BillingFacade {
  constructor(private gateway: BillingGateway, private tax: TaxService, private notify: Notifier) {}

  async createInvoice(order: Order) {
    const charge = await this.gateway.charge(order);
    const taxes = await this.tax.calculate(order);
    await this.notify.sendInvoice(order.contact, charge.id, taxes);
    return { charge, taxes };
  }
}

/* Version B */
class BillingCoordinator {
  constructor(public gateway: BillingGateway, public tax: TaxService, public notify: Notifier) {}

  async createInvoice(order: Order) {
    return { gateway: this.gateway, tax: this.tax, notify: this.notify };
  }
}
